CREATE TRIGGER RefCurrency_Version_Create
	ON RefCurrency
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT RX_PK, 'RX'
	FROM inserted
GO
CREATE TRIGGER RefCurrency_Version_Update
	ON RefCurrency
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON RX_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
